const int maxn=100005,maxq=100005,maxt=34;
const int inf=0x3f3f3f3f;
int a[maxn];
struct Segment{
	int l,r;
	Segment(int l=inf,int r=-inf):
		l(l),r(r){}
	Segment operator * (const Segment o)const{
		return Segment(min(l,o.l),max(r,o.r));
	}
	bool operator != (const Segment o)const{
		return l!=o.l||r!=o.r;
	}
	void input(void){
		read(l),read(r);
	}
}sg[maxt][maxn],tr[maxn],qy[maxq];
int n;
void res(void){
	for(int i=1;i<n;++i)
		tr[i]=Segment();
}
void add(int p,Segment v){
	while(p<n){
		tr[p]=tr[p]*v;
		p+=(p&(-p));
	}
}
Segment ask(int p){
	Segment re;
	while(p){
		re=re*tr[p];
		p^=(p&(-p));
	}
	return re;
}
struct Edge{
	int v,w,nt;
	Edge(int v=0,int w=0,int nt=0):
		v(v),w(w),nt(nt){}
}e[maxn];
int num,hd[maxn];
void ins(int u,int v,int w){
	e[++num]=Edge(v,w,hd[u]),hd[u]=num;
}
int st[maxq],tp;
long long Ans[maxq];
int main(){
	int q;read(n),read(q);
	if(n==1){while(q--)puts("0");return 0;}
	for(int i=1;i<=n;++i)read(a[i]);
	for(int i=1;i<n;++i){
		 if(a[i]<=a[i+1])
		 	sg[0][i]=Segment(a[i],a[i+1]);
		else
			sg[0][i]=Segment(a[i+1],a[i]);
	}
	for(int i=1;i<maxt;++i){
		for(int j=1;j<n;++j){
			if(sg[i-1][j].l>=sg[i-1][j].r)sg[i][j]=Segment();
			else ins(sg[i-1][j].l,sg[i-1][j].r-1,j);
		}
		res();
		for(int j=n-1;j>=1;--j){
			add(j,sg[i-1][j]);
			for(int k=hd[j];k;k=e[k].nt){
				sg[i][e[k].w]=ask(e[k].v);
			}
			hd[j]=0;
		}
		num=0;
	}
	for(int i=1;i<=q;++i){
		qy[i].input();
		if(qy[i].l==qy[i].r)Ans[i]=-2;
		else ins(qy[i].l,qy[i].r-1,i);
	}
	res();
	for(int i=n-1;i>=1;--i){
		add(i,sg[maxt-1][i]);
		for(int j=hd[i];j;j=e[j].nt){
			if(i==1&&e[j].v==n-1)
				Ans[e[j].w]=-1;
			else if(ask(e[j].v)!=Segment(1,n))
				Ans[e[j].w]=-2;
			else
				st[++tp]=e[j].w;
		}
		hd[i]=0;
	}
	num=0;
	for(int i=maxt-2;~i;--i){
		for(int j=1;j<=tp;++j){
			ins(qy[st[j]].l,qy[st[j]].r-1,st[j]);
		}
		res();
		for(int j=n-1;j>=1;--j){
			add(j,sg[i][j]);
			for(int k=hd[j];k;k=e[k].nt){
				Segment tmp=ask(e[k].v);
				int id=e[k].w;
				if(tmp!=Segment(1,n))
					Ans[id]|=(1ll<<i),qy[id]=tmp;
			}
			hd[j]=0;
		}
		num=0;
	}
	for(int i=1;i<=q;++i)
		write(++Ans[i]),pc('\n');
	return 0;
}

